import Foundation
import KodizBridgeProtocol

public enum NetscapeCookieExporter {
    /// Formats cookies into Netscape HTTP Cookie File format with #HttpOnly_ prefixes
    public static func format(cookies: [BridgeCookie]) -> String {
        var lines: [String] = [
            "# Netscape HTTP Cookie File",
            "# https://curl.se/docs/http-cookies.html",
            "# This file was generated by Kodiz Download Manager. Do not edit.",
            ""
        ]

        for cookie in cookies {
            let domain = cookie.domain ?? ""
            let includeSubdomains = domain.hasPrefix(".") ? "TRUE" : "FALSE"
            let path = cookie.path ?? "/"
            let secure = (cookie.secure ?? false) ? "TRUE" : "FALSE"
            let expires = Int64(cookie.expirationDate ?? Date().addingTimeInterval(86400 * 30).timeIntervalSince1970)
            let name = cookie.name
            let value = cookie.value

            var prefix = ""
            if cookie.httpOnly == true {
                prefix = "#HttpOnly_"
            }

            lines.append("\(prefix)\(domain)\t\(includeSubdomains)\t\(path)\t\(secure)\t\(expires)\t\(name)\t\(value)")
        }

        return lines.joined(separator: "\n") + "\n"
    }

    /// Writes cookie string to a temporary file with secure 0600 permissions
    public static func writeToSecureTempFile(cookies: [BridgeCookie], downloadId: UUID) throws -> URL {
        let content = format(cookies: cookies)
        let tempDir = FileManager.default.temporaryDirectory
        let fileURL = tempDir.appendingPathComponent("kdm-cookies-\(downloadId.uuidString).txt")

        let data = Data(content.utf8)
        FileManager.default.createFile(atPath: fileURL.path, contents: data, attributes: [
            .posixPermissions: 0o600
        ])

        return fileURL
    }
}
